"use client";

import { AnimatedList, AnimatedListItem } from "@/components/custom/blocks/AnimatedListBlock";
import { AnimatedNumber } from "@/components/custom/blocks/AnimatedNumberBlock";
import { cn } from "@/lib/utils";
import { Check, ChevronDown, Cloud, Globe, Loader2, Mail, Server, Zap } from "lucide-react";
import { useEffect, useRef, useState } from "react";

type Status = "idle" | "paying" | "paid" | "failed";
type FilterId = "all" | "soon" | "autopay";

const FILTERS: { id: FilterId; label: string }[] = [
  { id: "all", label: "All" },
  { id: "soon", label: "Due soon" },
  { id: "autopay", label: "Autopay" },
];

const SOON_DAYS = 6;

const subscriptions = [
  { id: "hosting", name: "Cloud hosting", amount: 48, dueInDays: 2, autopay: true, icon: Server },
  { id: "domain", name: "Domain renewal", amount: 14.99, dueInDays: 5, icon: Globe },
  { id: "email", name: "Email delivery", amount: 29, dueInDays: 11, autopay: true, icon: Mail },
  { id: "storage", name: "Object storage", amount: 18.4, dueInDays: 16, icon: Cloud },
  { id: "analytics", name: "Analytics", amount: 79, dueInDays: 23, icon: Zap },
];
type Subscription = (typeof subscriptions)[number];

const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

// Demo only: the first Domain payment is declined so you can see Retry.
const declined = new Set<string>();
async function pay(item: Subscription) {
  await new Promise((resolve) => setTimeout(resolve, 900));
  if (item.id === "domain" && !declined.has(item.id)) {
    declined.add(item.id);
    throw new Error("Card declined");
  }
}

const dueLabel = (days: number) =>
  days <= 0 ? "Due today" : days === 1 ? "Due tomorrow" : `Due in ${days} days`;

// The row's own look. AnimatedList only animates it; nothing here is required.
function PaymentRow({
  item,
  status,
  onPay,
}: {
  item: Subscription;
  status: Status;
  onPay: () => void;
}) {
  const Icon = item.icon;
  const amount = money.format(item.amount);
  const paying = status === "paying";
  const paid = status === "paid";
  const failed = status === "failed";

  return (
    <div
      className={cn(
        "group/row flex items-center gap-3 rounded-[1.75rem] bg-card p-3 pr-4 text-card-foreground",
        "shadow-[0_1px_2px_rgba(0,0,0,0.04),0_12px_32px_-16px_rgba(0,0,0,0.18)] ring-1 ring-[#F7F7F6] dark:ring-border/60",
        "transition-[background-color] duration-200 hover:bg-muted/50 focus-within:bg-muted/50",
        (paying || failed) && "bg-muted/50",
      )}
    >
      <span
        aria-hidden="true"
        className={cn(
          "flex size-10 shrink-0 items-center justify-center rounded-full transition-colors duration-300",
          failed
            ? "bg-destructive/10 text-destructive"
            : paid
              ? "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400"
              : "bg-background text-muted-foreground group-hover/row:bg-muted",
        )}
      >
        <Icon className="size-[18px]" />
      </span>

      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium text-foreground">{item.name}</p>
        <div className="mt-1 flex flex-wrap items-center gap-1.5 text-xs">
          {failed ? (
            <span className="rounded-full bg-destructive/10 px-2 py-0.5 font-medium text-destructive">
              Payment failed
            </span>
          ) : paid ? (
            <span className="text-muted-foreground">Paid</span>
          ) : item.dueInDays <= SOON_DAYS ? (
            <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-500/15 px-2 py-0.5 font-medium text-amber-700 dark:text-amber-400">
              <span className="relative flex size-1.5">
                <span className="absolute inset-0 rounded-full bg-current opacity-60 motion-safe:animate-ping" />
                <span className="relative size-1.5 rounded-full bg-current" />
              </span>
              {dueLabel(item.dueInDays)}
            </span>
          ) : (
            <span className="text-muted-foreground">{dueLabel(item.dueInDays)}</span>
          )}
          {item.autopay && !paid ? (
            <span className="rounded-full border border-border px-2 py-0.5 font-medium text-muted-foreground">
              Autopay
            </span>
          ) : null}
        </div>
      </div>

      <div className="grid shrink-0 select-none items-center justify-items-stretch [&>*]:col-start-1 [&>*]:row-start-1">
        {paid ? (
          <span className="inline-flex h-8 items-center gap-1.5 rounded-full bg-emerald-500/10 px-3 text-sm font-medium text-emerald-700 dark:text-emerald-400">
            <Check className="size-4" strokeWidth={3} aria-hidden="true" />
            Paid
          </span>
        ) : failed ? (
          <button
            type="button"
            onClick={onPay}
            className="h-8 cursor-pointer rounded-full bg-destructive/10 px-4 text-sm font-medium text-destructive transition-colors hover:bg-destructive/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-destructive/50"
          >
            Retry
          </button>
        ) : (
          <>
            {/* The amount fades out under the row hover; the Pay button fades in. */}
            <span
              aria-hidden="true"
              className={cn(
                "pointer-events-none inline-flex h-8 min-w-[4.5rem] items-center justify-center rounded-full bg-muted px-3 text-sm font-medium tabular-nums text-foreground transition-[opacity,filter] duration-200",
                paying
                  ? "opacity-0 blur-[3px]"
                  : "group-hover/row:opacity-0 group-hover/row:blur-[3px] group-focus-within/row:opacity-0 group-focus-within/row:blur-[3px]",
              )}
            >
              {amount}
            </span>
            <button
              type="button"
              disabled={paying}
              aria-busy={paying}
              aria-label={`Pay ${item.name}, ${amount}`}
              onClick={onPay}
              className={cn(
                "inline-flex h-8 min-w-[4.5rem] cursor-pointer items-center justify-center rounded-full bg-foreground px-3 text-sm font-medium text-background transition-[opacity,filter] duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                paying
                  ? "opacity-100"
                  : "opacity-0 blur-[3px] group-hover/row:opacity-100 group-hover/row:blur-none group-focus-within/row:opacity-100 group-focus-within/row:blur-none",
              )}
            >
              {paying ? <Loader2 className="size-4 animate-spin" aria-hidden="true" /> : "Pay"}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

function FilterMenu({
  value,
  onChange,
}: {
  value: FilterId;
  onChange: (value: FilterId) => void;
}) {
  const [open, setOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (!menuRef.current?.contains(target) && !triggerRef.current?.contains(target)) {
        setOpen(false);
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKey);
    menuRef.current?.querySelector<HTMLElement>('[aria-checked="true"]')?.focus();
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const onMenuKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const items = Array.from(
      e.currentTarget.querySelectorAll<HTMLElement>('[role="menuitemradio"]'),
    );
    const at = items.indexOf(document.activeElement as HTMLElement);
    const next =
      e.key === "ArrowDown"
        ? (at + 1) % items.length
        : e.key === "ArrowUp"
          ? (at - 1 + items.length) % items.length
          : e.key === "Home"
            ? 0
            : e.key === "End"
              ? items.length - 1
              : -1;
    if (next < 0) return;
    e.preventDefault();
    items[next].focus();
  };

  return (
    <div className="relative">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" && !open) {
            e.preventDefault();
            setOpen(true);
          }
        }}
        className="inline-flex h-8 cursor-pointer items-center gap-1.5 rounded-full bg-muted pl-3.5 pr-2.5 text-sm font-medium text-foreground transition-colors hover:bg-muted/70 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {FILTERS.find((f) => f.id === value)?.label}
        <ChevronDown
          className={cn("size-4 text-muted-foreground transition-transform duration-300", open && "rotate-180")}
          aria-hidden="true"
        />
      </button>
      <div
        ref={menuRef}
        role="menu"
        aria-label="Filter"
        onKeyDown={onMenuKeyDown}
        className={cn(
          "absolute right-0 top-full z-20 mt-2 w-40 rounded-2xl border border-border bg-popover p-1 text-popover-foreground shadow-lg transition-[opacity,filter,visibility] duration-200",
          open ? "visible opacity-100 blur-none" : "invisible opacity-0 blur-sm",
        )}
      >
        {FILTERS.map((f) => (
          <button
            key={f.id}
            type="button"
            role="menuitemradio"
            aria-checked={f.id === value}
            tabIndex={-1}
            onClick={() => {
              onChange(f.id);
              setOpen(false);
              triggerRef.current?.focus();
            }}
            className="flex w-full cursor-pointer items-center justify-between rounded-xl px-3 py-2 text-left text-sm text-foreground hover:bg-muted focus-visible:bg-muted focus-visible:outline-none"
          >
            {f.label}
            {f.id === value ? <Check className="size-4" aria-hidden="true" /> : null}
          </button>
        ))}
      </div>
    </div>
  );
}

export default function UpcomingPayments() {
  const [filter, setFilter] = useState<FilterId>("all");
  const [statuses, setStatuses] = useState<Record<string, Status>>({});

  const statusOf = (id: string): Status => statuses[id] ?? "idle";
  const total = subscriptions.reduce(
    (sum, s) => (statusOf(s.id) === "paid" ? sum : sum + s.amount),
    0,
  );
  const visible = subscriptions.filter(
    (s) => filter === "all" || (filter === "soon" ? s.dueInDays <= SOON_DAYS : s.autopay),
  );

  const payItem = async (item: Subscription) => {
    setStatuses((s) => ({ ...s, [item.id]: "paying" }));
    try {
      await pay(item);
      setStatuses((s) => ({ ...s, [item.id]: "paid" }));
    } catch {
      setStatuses((s) => ({ ...s, [item.id]: "failed" }));
    }
  };

  return (
    <div className="w-full max-w-md rounded-[2rem] bg-muted/60 p-2.5 dark:bg-muted/40">
      <div className="flex items-start justify-between gap-4 px-3 pb-1 pt-2">
        <div>
          <h3 className="text-sm font-medium text-muted-foreground">Coming up</h3>
          <AnimatedNumber
            value={total}
            format={(n) => money.format(n)}
            className="mt-1 block text-3xl font-semibold tracking-tight text-foreground"
          />
        </div>
        <FilterMenu value={filter} onChange={setFilter} />
      </div>

      <AnimatedList className="mt-3 flex flex-col gap-2.5">
        {visible.map((item) => (
          <AnimatedListItem key={item.id}>
            <PaymentRow
              item={item}
              status={statusOf(item.id)}
              onPay={() => payItem(item)}
            />
          </AnimatedListItem>
        ))}
      </AnimatedList>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import gsap from "gsap";
import React, {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { prefersReducedMotion } from "./gsap-motion";
import { useInView } from "./in-view";

const BLUR_OUT = { opacity: 0, filter: "blur(6px)" };
const BLUR_IN = { opacity: 1, filter: "blur(0px)" };

/** Whether the list's entrance has played; items added after that animate alone. */
const ListContext = createContext({ revealed: false });

function mergeRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as React.MutableRefObject<T | null>).current = node;
    }
  };
}

export interface AnimatedListProps extends React.HTMLAttributes<HTMLElement> {
  /** The element to render. Use "div" when the items are not list items. */
  as?: "ul" | "ol" | "div";
  /** Seconds between one item starting its entrance and the next. */
  staggerDelay?: number;
  /** Entrance duration of each item, in seconds. */
  duration?: number;
}

/**
 * A list whose items rise and blur in one after another when it scrolls into
 * view. Put `AnimatedListItem`s inside; items you add later fade in, items you
 * remove fade out, and the others glide to their new place.
 */
export const AnimatedList = forwardRef<HTMLElement, AnimatedListProps>(
  ({ as = "ul", staggerDelay = 0.07, duration = 0.55, className, ...props }, ref) => {
    const rootRef = useRef<HTMLElement | null>(null);
    const [watch, inView] = useInView();
    const [revealed, setRevealed] = useState(false);

    const setRoot = useCallback(
      (node: HTMLElement | null) => {
        rootRef.current = node;
        watch(node);
      },
      [watch],
    );

    useEffect(() => {
      if (!inView || revealed) return;
      const items = rootRef.current?.querySelectorAll(":scope > [data-animated-item]");
      if (items?.length && !prefersReducedMotion()) {
        gsap.fromTo(
          items,
          { ...BLUR_OUT, y: 14 },
          {
            ...BLUR_IN,
            y: 0,
            duration,
            ease: "power3.out",
            stagger: staggerDelay,
            clearProps: "filter,transform",
          },
        );
      }
      setRevealed(true);
    }, [inView, revealed, duration, staggerDelay]);

    return (
      <ListContext.Provider value={{ revealed }}>
        {React.createElement(as, {
          ...props,
          ref: mergeRefs(setRoot, ref as React.Ref<HTMLElement>),
          className: cn("relative", className),
        })}
      </ListContext.Provider>
    );
  },
);
AnimatedList.displayName = "AnimatedList";

export interface AnimatedListItemProps extends React.HTMLAttributes<HTMLElement> {
  /** The element to render. Use "div" inside an `as="div"` list. */
  as?: "li" | "div";
}

/**
 * One animated row. Give it a stable `key`: that is how the list tells an item
 * that was added, removed or moved from one that stayed.
 */
export const AnimatedListItem = forwardRef<HTMLElement, AnimatedListItemProps>(
  ({ as = "li", className, ...props }, ref) => {
    const { revealed } = useContext(ListContext);
    const itemRef = useRef<HTMLElement | null>(null);
    const revealedRef = useRef(revealed);
    revealedRef.current = revealed;
    const lastBox = useRef<{ top: number; left: number } | null>(null);

    // After every commit: fade in when new, glide when something moved it.
    // Layout positions are read (offsetTop/Left), so running animations never
    // count as movement.
    useLayoutEffect(() => {
      const el = itemRef.current;
      if (!el) return;
      const box = { top: el.offsetTop, left: el.offsetLeft };
      const prev = lastBox.current;
      lastBox.current = box;
      if (prefersReducedMotion()) return;

      if (!prev) {
        if (revealedRef.current) {
          gsap.fromTo(el, BLUR_OUT, { ...BLUR_IN, duration: 0.4, delay: 0.1, clearProps: "filter" });
        }
        return;
      }
      const dx = prev.left - box.left;
      const dy = prev.top - box.top;
      if (!dx && !dy) return;
      gsap.fromTo(
        el,
        { x: Number(gsap.getProperty(el, "x")) + dx, y: Number(gsap.getProperty(el, "y")) + dy },
        { x: 0, y: 0, duration: 0.5, ease: "power3.inOut", overwrite: "auto" },
      );
    });

    // On removal, a copy stays behind and fades out where the item stood.
    useLayoutEffect(() => {
      const el = itemRef.current;
      return () => {
        const parent = el?.parentElement;
        if (!el || !parent || !revealedRef.current || prefersReducedMotion()) return;
        const ghost = el.cloneNode(true) as HTMLElement;
        ghost.removeAttribute("data-animated-item");
        ghost.querySelectorAll("[id]").forEach((n) => n.removeAttribute("id"));
        ghost.setAttribute("aria-hidden", "true");
        ghost.setAttribute("inert", "");
        Object.assign(ghost.style, {
          position: "absolute",
          top: `${el.offsetTop}px`,
          left: `${el.offsetLeft}px`,
          width: `${el.offsetWidth}px`,
          height: `${el.offsetHeight}px`,
          margin: "0",
          pointerEvents: "none",
        });
        parent.appendChild(ghost);
        gsap.to(ghost, {
          ...BLUR_OUT,
          duration: 0.3,
          ease: "power2.out",
          onComplete: () => ghost.remove(),
        });
      };
    }, []);

    return React.createElement(as, {
      ...props,
      "data-animated-item": "",
      ref: mergeRefs(itemRef, ref as React.Ref<HTMLElement>),
      className: cn(!revealed && "opacity-0", className),
    } as React.HTMLAttributes<HTMLElement>);
  },
);
AnimatedListItem.displayName = "AnimatedListItem";

import gsap from "gsap";
import { cubicBezier, type FrameTicker } from "./motion-curves";

/**
 * GSAP-side glue for the GSAP builds of components that also ship a Motion
 * Motion twin. Kept apart from motion-curves.ts so the library-free curves
 * never pull GSAP into a CSS or Motion build.
 */

/** `gsap.ticker` as a FrameTicker, so spring followers run on GSAP's loop. */
export const gsapTicker: FrameTicker = {
  add(callback) {
    const tick = (_time: number, deltaTime: number) => callback(deltaTime);
    gsap.ticker.add(tick);
    return () => gsap.ticker.remove(tick);
  },
};

/** A Motion / CSS cubic-bezier array as a GSAP ease. */
export const bezierEase = (curve: readonly [number, number, number, number] | readonly number[]) =>
  cubicBezier(curve[0], curve[1], curve[2], curve[3]);

/** `(prefers-reduced-motion: reduce)` right now. */
export const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

"use client";

import { useEffect, useState } from "react";

/**
 * True once the element has scrolled into view, and stays true. Hand `watch`
 * to the element's `ref`.
 */
export function useInView(threshold = 0.25) {
  const [node, setNode] = useState<Element | null>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    if (!node) return;
    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          io.disconnect();
        }
      },
      { threshold },
    );
    io.observe(node);
    return () => io.disconnect();
  }, [node, threshold]);

  return [setNode, inView] as const;
}

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}

"use client";

import { cn } from "@/lib/utils";
import gsap from "gsap";
import React, { useEffect, useRef } from "react";
import { prefersReducedMotion } from "./gsap-motion";
import { useInView } from "./in-view";

export interface AnimatedNumberProps extends React.HTMLAttributes<HTMLSpanElement> {
  value: number;
  /** Turns the running number into text. Defaults to `toLocaleString()`. */
  format?: (value: number) => string;
  /** Seconds each count takes. */
  duration?: number;
}

/**
 * A number that counts up when it scrolls into view, then counts from where it
 * is to every new `value`. Screen readers get the final value, not the count.
 */
export function AnimatedNumber({
  value,
  format = (n) => n.toLocaleString(),
  duration = 0.9,
  className,
  ...props
}: AnimatedNumberProps) {
  const [watch, inView] = useInView();
  const textRef = useRef<HTMLSpanElement>(null);
  const shown = useRef({ value: 0 });
  const formatRef = useRef(format);
  formatRef.current = format;

  useEffect(() => {
    const el = textRef.current;
    if (!el) return;
    const write = () => {
      el.textContent = formatRef.current(shown.current.value);
    };
    if (!inView || prefersReducedMotion()) {
      shown.current.value = inView ? value : 0;
      write();
      return;
    }
    const tween = gsap.to(shown.current, {
      value,
      duration,
      ease: "power3.out",
      onUpdate: write,
      onComplete: write,
    });
    return () => {
      tween.kill();
    };
  }, [value, inView, duration]);

  return (
    <span ref={watch} className={cn("tabular-nums", className)} {...props}>
      <span className="sr-only">{format(value)}</span>
      <span ref={textRef} aria-hidden="true" />
    </span>
  );
}
